namespace CycloneDDS.Core
{
    /// <summary>
    /// Implemented by the code generator on every <c>[DdsStruct]</c> type. Binds the type to its
    /// XCDR serializer and the idlc topic descriptor at compile time.
    /// </summary>
    public interface IDdsType<TSelf> where TSelf : IDdsType<TSelf>
    {
        /// <summary>Topic descriptor generated by idlc from the type's IDL.</summary>
        static abstract DdsTypeDescriptor Descriptor { get; }

        /// <summary>Appends the members of <paramref name="value"/> to <paramref name="writer"/>.</summary>
        static abstract void Serialize(ref CdrWriter writer, in TSelf value);

        /// <summary>Reads one value from <paramref name="reader"/>.</summary>
        static abstract TSelf Deserialize(ref CdrReader reader);
    }

    /// <summary>
    /// The parts of a native <c>dds_topic_descriptor_t</c> that idlc computes for a type.
    /// Cyclone validates every sample against <see cref="Ops"/>.
    /// </summary>
    /// <param name="typeName">Scoped IDL name, which is also the DDS type name on the wire.</param>
    /// <param name="ops">Serializer opcodes.</param>
    /// <param name="flagset">Descriptor flags.</param>
    /// <param name="size">Size of the C representation of the type.</param>
    /// <param name="align">Alignment of the C representation of the type.</param>
    public sealed class DdsTypeDescriptor(string typeName, uint[] ops, uint flagset, uint size, uint align)
    {
        public string TypeName { get; } = typeName;
        public uint[] Ops { get; } = ops;
        public uint Flagset { get; } = flagset;
        public uint Size { get; } = size;
        public uint Align { get; } = align;
    }
}
